insert into public.actors (id, name, stage_name, tagline, birthdate, hometown, network, agency, generation, gender, decades, genres, base_fans, bio, photo_url, socials, spotlight, trending_rank, created_by) values
  ('amihan-reyes', 'Amihan Reyes', 'Ang Reyna ng Drama', 'Box-office royalty with four Best Actress trophies', '1991-03-14', 'Iloilo City, Iloilo', 'ABS-CBN', 'Star Magic', 'Millennial', 'Female', array['2010s', '2020s']::text[], array['Drama', 'Romance']::text[], 12400000, 'Discovered at sixteen in a mall talent search in Iloilo, Amihan Reyes spent five years in supporting roles before "Hanggang Umaga" turned her into the most bankable dramatic lead of her generation. Critics point to her stillness — long, unblinking takes that carry an entire scene without dialogue. She now splits her time between primetime teleseryes and independent films, and produces two of them a year through her own outfit, Habagat Pictures.', '/seed/actors/amihan-reyes.png', '{"instagram":"@amihanreyes","x":"@amihanreyes","tiktok":"@amihan"}'::jsonb, true, 4, null),
  ('liway-santillan', 'Liwayway Santillan', 'Liway', 'Kapuso primetime lead and 2024 Gawad Sining honoree', '1993-08-02', 'Lipa, Batangas', 'GMA', 'Sparkle GMA Artist Center', 'Millennial', 'Female', array['2010s', '2020s']::text[], array['Drama', 'Fantasy', 'Romance']::text[], 8900000, 'Liway came up through fantaseryes, where she learned to sell the impossible with a straight face — and then spent the next decade proving she could do the same with ordinary heartbreak. Her turn as a working mother in "Gabi ng Liwanag" was the highest-rated Kapuso finale in six years. Offscreen she runs a scholarship fund for public-school drama students in Batangas.', '/seed/actors/liway-santillan.png', '{"instagram":"@liwaysantillan","tiktok":"@liway"}'::jsonb, false, 2, null),
  ('manny-dalisay', 'Emmanuel Dalisay', 'Manny D', 'Action-comedy lead turned indie-film favorite', '1990-11-28', 'Cebu City, Cebu', 'Viva', 'Viva Artists Agency', 'Millennial', 'Male', array['2010s', '2020s']::text[], array['Action', 'Comedy', 'Drama']::text[], 6200000, 'Manny Dalisay started as a stuntman on Viva action pictures and still does most of his own falls. His comic timing was an accident — a director kept the improvised takes — and it made him the rare Filipino leading man who opens both an action tentpole and a two-hander shot on a single Cebu street. He is unusually protective of his rest days and has spoken publicly about set safety.', '/seed/actors/manny-dalisay.png', '{"instagram":"@mannydalisay","x":"@mannyd"}'::jsonb, true, null, null),
  ('charing-villanueva', 'Rosario Villanueva', 'Tita Charing', 'Five decades on screen, and the Kapamilya matriarch of them all', '1961-06-09', 'Vigan, Ilocos Sur', 'ABS-CBN', 'Star Magic', 'Legends', 'Female', array['1980s', '1990s', '2000s', '2010s', '2020s']::text[], array['Drama', 'Period', 'Comedy']::text[], 4100000, 'Rosario "Charing" Villanueva made her first film in 1979 and has not gone a year without a credit since. She is the industry''s reigning matriarch — the mother, the lola, the judge — and the person younger actors quote when asked about discipline. Her one-take monologue in "Ang Huling Liham" is taught in film schools. She was named a National Artist nominee for Film in 2024.', '/seed/actors/charing-villanueva.png', '{"instagram":"@titacharing"}'::jsonb, true, null, null),
  ('nanding-aguilar', 'Fernando Aguilar', 'Nanding', 'The Kapuso character actor who steals every scene', '1959-01-22', 'Malolos, Bulacan', 'GMA', 'GMA Artist Center', 'Legends', 'Male', array['1980s', '1990s', '2000s', '2010s', '2020s']::text[], array['Drama', 'Period', 'Action']::text[], 2700000, 'A stage actor first, Fernando Aguilar spent the eighties in Bulacan community theater before television found him. He has played the father, the villain, the priest and the president — often in the same season — and remains the industry''s most requested table-read partner for young leads. He teaches a free Saturday acting workshop in Malolos that has run for nineteen years.', '/seed/actors/nanding-aguilar.png', '{"instagram":"@nandingaguilar","x":"@nandinga"}'::jsonb, false, 5, null),
  ('bibi-manalo', 'Bianca Manalo', 'Bibi', 'The Gen Z breakout with 3.2M in eight months', '2003-02-17', 'Davao City, Davao del Sur', 'ABS-CBN', 'Star Magic', 'Gen Z', 'Female', array['2020s']::text[], array['Romance', 'Comedy', 'Drama']::text[], 3200000, 'Bibi Manalo posted a two-minute monologue from her Davao bedroom in 2024; it was reposted by a casting director and she was on a Star Magic set within the month. She has since carried a streaming romance and a horror anthology episode, and is the youngest actress ever shortlisted for a Gawad Urian acting nod. She still edits her own vlogs.', '/seed/actors/bibi-manalo.png', '{"instagram":"@bibimanalo","tiktok":"@bibi"}'::jsonb, false, 1, null),
  ('rafa-ocampo', 'Rafael Ocampo', 'Rafa', 'Sparkle''s young leading man and reluctant heartthrob', '2001-09-05', 'Baguio City, Benguet', 'GMA', 'Sparkle GMA Artist Center', 'Gen Z', 'Male', array['2020s']::text[], array['Romance', 'Comedy', 'Action']::text[], 2900000, 'Rafa Ocampo was a competitive swimmer in Baguio until a shampoo commercial changed the plan. Three years in, he has learned to lean away from the heartthrob framing — his best work so far is a quiet, unglamorous turn as a delivery rider in "Kalye Kings". He is currently studying film production between shoots.', '/seed/actors/rafa-ocampo.png', '{"instagram":"@rafaocampo","tiktok":"@rafa"}'::jsonb, false, 3, null),
  ('dindo-salazar', 'Rodolfo Salazar', 'Dindo', 'The Kapatid comedy king who never misses a punchline', '1965-04-30', 'San Fernando, Pampanga', 'TV5', 'Cornerstone Talents', 'Legends', 'Male', array['1980s', '1990s', '2000s', '2010s', '2020s']::text[], array['Comedy', 'Drama']::text[], 3800000, 'Dindo Salazar started out doing impressions at Pampanga fiestas and hasn''t stopped making the country laugh since. His Sunday sitcom "Bahay ni Kuya Dindo" ran for eleven seasons, and his late-career dramatic turn as a grieving jeepney driver surprised critics who had only seen the clown. He still writes his own material and tests every joke on his grandchildren first.', '/seed/actors/dindo-salazar.png', '{"instagram":"@dindosalazar","x":"@kuyadindo"}'::jsonb, false, null, null),
  ('isay-dimaculangan', 'Maria Luisa Dimaculangan', 'Isay', 'Queen of Pinoy horror with a scream heard nationwide', '1992-10-31', 'Legazpi City, Albay', 'TV5', 'Cornerstone Talents', 'Millennial', 'Female', array['2010s', '2020s']::text[], array['Horror', 'Drama', 'Fantasy']::text[], 5100000, 'Isay Dimaculangan grew up on her lola''s aswang stories in the shadow of Mayon, and she brings that folklore to every role. Her "Tiyanak Trilogy" is the most-watched Filipino horror franchise on streaming, and she insists on doing her own underwater scenes. Between frights she hosts a podcast on Bicolano myths.', '/seed/actors/isay-dimaculangan.png', '{"instagram":"@isaydimaculangan","tiktok":"@isayscreams"}'::jsonb, true, null, null),
  ('kaloy-mendoza', 'Carlos Mendoza', 'Kaloy', 'Indie cinema''s quiet storm from Tacloban', '2000-12-08', 'Tacloban City, Leyte', 'Independent', 'Habagat Pictures', 'Gen Z', 'Male', array['2020s']::text[], array['Drama', 'Period']::text[], 1400000, 'Kaloy Mendoza was thirteen when Typhoon Yolanda flattened his neighborhood; a decade later he played a survivor in "Ang Batang Tubig" and made grown critics cry at Cinemalaya. He works almost exclusively in independent film, chooses projects by script alone, and has turned down two primetime teleserye offers to stay in Leyte with his family.', '/seed/actors/kaloy-mendoza.png', '{"instagram":"@kaloymendoza"}'::jsonb, false, 8, null),
  ('ligaya-tan', 'Ligaya Tan', 'Gaya', 'Viva''s rom-com sweetheart from Zamboanga', '2002-05-21', 'Zamboanga City, Zamboanga del Sur', 'Viva', 'Viva Artists Agency', 'Gen Z', 'Female', array['2020s']::text[], array['Romance', 'Comedy']::text[], 4600000, 'Gaya Tan sings, dances and speaks four languages — Chavacano, Tagalog, English and Hokkien — and uses all of them on set. Her streaming rom-com "Tadhana Delivery" topped the local charts for nine weeks. She is known for learning every crew member''s name by the second shooting day.', '/seed/actors/ligaya-tan.png', '{"instagram":"@ligayatan","tiktok":"@gaya"}'::jsonb, false, 6, null),
  ('ramon-estrella', 'Ramon Estrella', 'Mon', 'Kapamilya action star who trained with the Coast Guard', '1988-07-12', 'Cagayan de Oro, Misamis Oriental', 'ABS-CBN', 'Star Magic', 'Millennial', 'Male', array['2010s', '2020s']::text[], array['Action', 'Drama']::text[], 7300000, 'Mon Estrella spent six months with the Philippine Coast Guard preparing for "Bantay Dagat" and came out a certified rescue swimmer. The series made him primetime''s most reliable action lead, but his favorite role is the soft-spoken father in the family drama "Tahanan". He runs a free swimming clinic for kids every summer in Cagayan de Oro.', '/seed/actors/ramon-estrella.png', '{"instagram":"@monestrella","x":"@monestrella"}'::jsonb, false, 7, null)
