insert into public.news (id, headline, excerpt, body, source, minutes_read, published_at, image_url, tag, actor_id) values
  ('n1', 'Amihan Reyes takes home her fourth Best Actress trophy', 'The "Salamin" star swept the acting field at last night''s Gawad Sining, dedicating the win to her late acting coach in Iloilo.', 'Amihan Reyes walked into the Gawad Sining ballroom as the favorite and left with the night''s biggest prize, her fourth Best Actress trophy in six years.
insert into public.trivia_questions (id, prompt, actor_id, choices, answer_index, fact, position) values
  ('q1', 'Four Best Actress trophies and counting. Who is she?', 'amihan-reyes', array['Amihan Reyes', 'Liwayway Santillan', 'Bianca Manalo', 'Rosario Villanueva']::text[], 0, 'Amihan was discovered at sixteen in an Iloilo mall talent search.', 0),
  ('q2', 'This Kapuso lead began in fantaseryes. Name her.', 'liway-santillan', array['Bianca Manalo', 'Liwayway Santillan', 'Amihan Reyes', 'Rosario Villanueva']::text[], 1, '"Gabi ng Liwanag" gave GMA its highest-rated finale in six years.', 1),
  ('q3', 'Former stuntman, now an indie-film favorite. Who?', 'manny-dalisay', array['Rafael Ocampo', 'Fernando Aguilar', 'Emmanuel Dalisay', 'Nico Bautista']::text[], 2, 'Manny still performs most of his own falls.', 2),
  ('q4', 'Forty-six years on screen without a single gap year.', 'charing-villanueva', array['Amihan Reyes', 'Pilar Domingo', 'Liwayway Santillan', 'Rosario Villanueva']::text[], 3, 'Tita Charing was nominated as National Artist for Film in 2024.', 3),
  ('q5', 'A Davao bedroom monologue made this star famous. Who?', 'bibi-manalo', array['Bianca Manalo', 'Amihan Reyes', 'Liwayway Santillan', 'Yumi Cruz']::text[], 0, 'Bibi is the youngest actress ever shortlisted for a Gawad Urian acting nod.', 4),
  ('q6', 'Baguio swimmer turned Sparkle leading man.', 'rafa-ocampo', array['Emmanuel Dalisay', 'Rafael Ocampo', 'Fernando Aguilar', 'Migs Reyes']::text[], 1, 'A shampoo commercial ended Rafa''s competitive swimming career.', 5),
  ('q7', 'Eleven seasons of Sunday sitcom laughs. Who is this Kapatid legend?', 'dindo-salazar', array['Fernando Aguilar', 'Rodolfo Salazar', 'Emmanuel Dalisay', 'Ramon Estrella']::text[], 1, 'Dindo tests every joke on his grandchildren before it airs.', 6),
  ('q8', 'This horror queen does her own underwater scenes. Name her.', 'isay-dimaculangan', array['Maria Luisa Dimaculangan', 'Ligaya Tan', 'Bianca Manalo', 'Liwayway Santillan']::text[], 0, 'Isay hosts a podcast about Bicolano myths between films.', 7),
  ('q9', 'Indie star who turned down primetime to stay in Leyte.', 'kaloy-mendoza', array['Rafael Ocampo', 'Ramon Estrella', 'Carlos Mendoza', 'Emmanuel Dalisay']::text[], 2, 'Kaloy won Best Actor at the Gawad Urian for "Ang Batang Tubig".', 8),
  ('q10', 'She speaks Chavacano, Tagalog, English and Hokkien on set.', 'ligaya-tan', array['Bianca Manalo', 'Amihan Reyes', 'Maria Luisa Dimaculangan', 'Ligaya Tan']::text[], 3, '"Tadhana Delivery" topped the local streaming charts for nine weeks.', 9),
  ('q11', 'Certified rescue swimmer and primetime action lead. Who?', 'ramon-estrella', array['Ramon Estrella', 'Rafael Ocampo', 'Rodolfo Salazar', 'Carlos Mendoza']::text[], 0, 'Mon trained with the Philippine Coast Guard for six months for "Bantay Dagat".', 10),
  ('q12', 'Bulacan theater veteran with a free Saturday acting workshop.', 'nanding-aguilar', array['Rodolfo Salazar', 'Emmanuel Dalisay', 'Fernando Aguilar', 'Ramon Estrella']::text[], 2, 'Nanding''s Malolos workshop has run every Saturday for nineteen years.', 11)
